from fractions import Fraction as F
import json
# U=0 restricts the persistent latent row once; redisplay adds no evidence.
rows=[('A',5,(0,0,1)),('A',6,(1,1,0)),('B',11,(0,0,1)),('C',4,(1,1,1)),('D',6,(0,1,0))] # readings T,V,W
modes='ABCD'; tests='TVW'; costs=[F(7),F(17,10),F(21,10)]
L=[[0,7,10,21],[7,0,22,11],[19,13,0,19],[12,6,13,0]]
def repair(rs):
    mass=sum(r[1] for r in rs)
    return min((F(sum(r[1]*L[a][modes.index(r[0])] for r in rs),mass),modes[a]) for a in range(4))
mass=sum(r[1] for r in rows)
posterior={m:float(F(sum(r[1] for r in rows if r[0]==m),mass)) for m in modes}
values={m:F(sum(r[1]*L[a][modes.index(r[0])] for r in rows),mass) for a,m in enumerate(modes)}
branches={}
for j,t in enumerate(tests):
    val=costs[j]; branches[t]={}
    for b in (0,1):
        rs=[r for r in rows if r[2][j]==b]
        if not rs:
            branches[t][str(b)]='IMPOSSIBLE'
        else:
            risk,act=repair(rs)
            val+=F(sum(r[1] for r in rs),mass)*risk
            branches[t][str(b)]=act
    values[t]=val
action=min(values,key=values.get)
ans={'posterior':posterior,'remaining_losses':{k:float(v) for k,v in values.items()},'action':action,'repair_after':branches.get(action,{})}
# Independent chosen W check: W=0 weights A6,D6 -> D loss72; W=1 A5,B11,C4 -> B loss123.
assert values['W']==F(21,10)+F(72+123,32)
assert posterior=={'A':11/32,'B':11/32,'C':4/32,'D':6/32}
payload=json.dumps(ans)
assert json.loads(payload)['action']==action
print(payload)

