import json
from fractions import Fraction as F
modes='ABCD'
rows=[(0,5,(0,0,1)),(0,6,(1,1,0)),(1,11,(0,0,1)),(2,4,(1,1,1)),(3,6,(0,1,0))]
L=[[0,7,10,21],[7,0,22,11],[19,13,0,19],[12,6,13,0]]
def raw(rs): return min((sum(w*L[a][m] for m,w,r in rs),modes[a]) for a in range(4))
p={m:sum(w for a,w,r in rows if a==i)/32 for i,m in enumerate(modes)}
v={m:F(sum(w*L[i][a] for a,w,r in rows),32) for i,m in enumerate(modes)}
br={}
for j,(t,c) in enumerate(zip('TVW',[F(7),F(17,10),F(21,10)])):
    v[t]=c;br[t]={}
    for b in (0,1):
        sub=[r for r in rows if r[2][j]==b]
        n,a=raw(sub);v[t]+=F(n,32);br[t][str(b)]=a
assert v['W']==F(21,10)+F(189,32)
assert v['V']==F(17,10)+F(159,32)
a=min(v,key=v.get)
print(json.dumps({'posterior':p,'remaining_losses':{k:float(x) for k,x in v.items()},'action':a,'repair_after':br.get(a,{})}))

